-- =====================================================================
-- Seed master obat (50 baris) -> tabel `barang` (apotek / ws_posindo_v2.1), id_client 12
-- Kolom & nilai default sama dengan form Stok Obat (services/obat.js::payloadObat
-- + M_master_barang::create_barang): KATEGORI 'OBAT-OBATAN', JENIS 'OBAT',
-- POTONGSTOCK 1, UNTUK_DIJUAL 1, ARSIPKAN 0, DELETED 0.
-- Harga (HARGABELI/HARGAJUAL) per satuan KECIL. Stok/batch TIDAK dibuat di sini
-- (masuk lewat Penerimaan atau "Tambah batch" di Stok Obat).
-- IDBARANG & BARCODE: nomor urut 6 digit, melanjutkan IDBARANG terbesar milik klien ini.
-- CODE_SEDIAAN / KODE_RUTE memakai konvensi kode otomatis aplikasi (nama dihuruf besar);
-- sesuaikan bila master m_bentuk_sediaan / rute di database memakai kode lain.
-- Jalankan SEKALI. Untuk mengulang, hapus dulu baris yang sama.
-- =====================================================================
SET @IDCLIENT := 12;
SET @n := (SELECT IFNULL(MAX(CAST(IDBARANG AS UNSIGNED)), 0) FROM barang WHERE IDCLIENT = @IDCLIENT);

-- (opsional) cek duplikat sebelum insert, hasil harus 0:
-- SELECT COUNT(*) FROM barang WHERE IDCLIENT = @IDCLIENT AND DELETED = 0 AND NAMA IN ('PARACETAMOL 500 MG TABLET', 'AMOXICILLIN 500 MG KAPSUL');

INSERT INTO barang
