   SATUAN_KECIL, SATUAN, SATUAN_SEDANG, SATUAN_BESAR, ISI_SEDANG_KE_KECIL, ISI_BESAR_KE_SEDANG,
   HARGABELI, HARGAJUAL, GROUPING,
   BENTUK_SEDIAAN, CODE_SEDIAAN, RUTE, KODE_RUTE, KANDUNGAN, SATUAN_KANDUNGAN, VOLUME_UOM_NAME,
   POTONGSTOCK, GUNAKAN_STOCK_MIN, STOCKMINIMUM, UNTUK_DIJUAL, IS_RENTAL_ITEM,
   ISKRONIS, ISKONSINYASI, NEED_TOBE_APROVE, GARANSI,
   KLASIFIKASI_OBAT, GOLONGAN, CATATAN, ARSIPKAN, DELETED, IDCLIENT)
